use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let arr = input.as_array().unwrap();
    let mut sorted_arr = arr.clone();
    sorted_arr.sort_unstable_by(|a, b| {
        if a[0] == b[0] {
            a[1].cmp(&b[1])
        } else {
            a[0].cmp(&b[0])
        }
    });
    Value::Array(sorted_arr)
}
